import {
  BottomSheetBackdrop,
  type BottomSheetBackdropProps,
  BottomSheetModal,
  type BottomSheetModalProps,
  BottomSheetView,
} from '@gorhom/bottom-sheet';
import { forwardRef, type ReactNode, useCallback } from 'react';

import { useThemeColors } from '@/theme';

export type AppBottomSheetRef = BottomSheetModal;

export interface AppBottomSheetProps extends Partial<BottomSheetModalProps> {
  children: ReactNode;
}

/**
 * Themed wrapper around `BottomSheetModal`. Present it imperatively:
 *
 *   const sheet = useRef<AppBottomSheetRef>(null);
 *   sheet.current?.present();
 *
 * Requires `<BottomSheetModalProvider>` at the app root (wired in app/_layout.tsx).
 */
export const AppBottomSheet = forwardRef<BottomSheetModal, AppBottomSheetProps>(
  function AppBottomSheet({ children, ...props }, ref) {
    const colors = useThemeColors();

    const renderBackdrop = useCallback(
      (backdropProps: BottomSheetBackdropProps) => (
        <BottomSheetBackdrop {...backdropProps} appearsOnIndex={0} disappearsOnIndex={-1} />
      ),
      [],
    );

    return (
      <BottomSheetModal
        ref={ref}
        enableDynamicSizing
        backdropComponent={renderBackdrop}
        backgroundStyle={{ backgroundColor: colors.card }}
        handleIndicatorStyle={{ backgroundColor: colors.mutedForeground }}
        {...props}
      >
        <BottomSheetView style={{ paddingBottom: 24 }}>{children}</BottomSheetView>
      </BottomSheetModal>
    );
  },
);
